"""Independent numerical/streaming checks for the twenty research masters.

Run from any directory with: python3 test_research_masters.py
Standard library only. These are mathematical reference and behavioral tests,
not trading-system backtests or implementations for the five target languages.
"""

from pathlib import Path
import importlib.util
import math
import random
import sys
import unittest
from datetime import date, timedelta

# Dynamic loading should not add generated bytecode to delivery folders.
sys.dont_write_bytecode = True
ROOT = Path(__file__).resolve().parent
MODULES = {}
for directory in sorted(ROOT.iterdir()):
    source = directory/(directory.name+'.py')
    if directory.is_dir() and source.is_file():
        name = 'lvt_'+directory.name.replace('-','_')
        spec = importlib.util.spec_from_file_location(name,source)
        module = importlib.util.module_from_spec(spec)
        sys.modules[name] = module
        spec.loader.exec_module(module)
        MODULES[directory.name] = module

STREAMING_MODULES = {slug:module for slug,module in MODULES.items()
                     if getattr(module,'DELIVERY_KIND','streaming') != 'model-cli'}


def same_number(test, left, right, tolerance=1e-10):
    if math.isnan(left) or math.isnan(right):
        test.assertTrue(math.isnan(left) and math.isnan(right))
    else:
        test.assertTrue(math.isclose(left,right,rel_tol=tolerance,abs_tol=tolerance),
                        f'{left!r} != {right!r}')


def dense_hp(values, smoothing):
    """Independent normal-equation construction and pivoted dense elimination."""
    n = len(values)
    matrix = [[float(i==j) for j in range(n)] for i in range(n)]
    for row in range(n-2):
        coefficients = (1.0,-2.0,1.0)
        for i in range(3):
            for j in range(3):
                matrix[row+i][row+j] += smoothing*coefficients[i]*coefficients[j]
    rhs = list(values)
    for column in range(n):
        pivot = max(range(column,n),key=lambda row:abs(matrix[row][column]))
        matrix[column],matrix[pivot] = matrix[pivot],matrix[column]
        rhs[column],rhs[pivot] = rhs[pivot],rhs[column]
        divisor = matrix[column][column]
        for row in range(column+1,n):
            multiplier = matrix[row][column]/divisor
            for j in range(column,n):
                matrix[row][j] -= multiplier*matrix[column][j]
            rhs[row] -= multiplier*rhs[column]
    result = [0.0]*n
    for row in range(n-1,-1,-1):
        result[row] = (rhs[row]-sum(matrix[row][j]*result[j] for j in range(row+1,n)))/matrix[row][row]
    return result


class StreamingContractTests(unittest.TestCase):
    def test_twenty_standalone_modules(self):
        self.assertEqual(len(MODULES),20)
        self.assertEqual(len(STREAMING_MODULES),18)

    def test_reset_nan_and_input_rejection_for_every_master(self):
        for slug,module in STREAMING_MODULES.items():
            with self.subTest(indicator=slug):
                arrays = module._load_arrays(ROOT/slug/'test_testdata.py')
                # Exercise a finite reduced-delay case for the Metonic masters.
                case = module.REFERENCE_CASES[2 if slug=='metonic-sentiment-index' else
                                              1 if slug.startswith('metonic-') else 0]
                parameters = case['params']
                clean = module.MASTER_CLASS(**parameters)
                interrupted = module.MASTER_CLASS(**parameters)
                originals = []
                for index,price in enumerate(arrays['INPUT_CLOSE']):
                    original = module.fixture_update(clean,index,price,arrays)
                    # An unavailable sample must not advance history or dates.
                    module.fixture_update(interrupted,index,math.nan,arrays)
                    if index==20:
                        with self.assertRaises(ValueError):
                            interrupted.update(math.inf)
                        with self.assertRaises(ValueError):
                            interrupted.update(True)
                    observed = module.fixture_update(interrupted,index,price,arrays)
                    left,right = module.flatten_output(clean,original),module.flatten_output(interrupted,observed)
                    self.assertEqual(set(left),set(right))
                    for key in left:
                        same_number(self,left[key],right[key],0.0)
                    originals.append(left)
                interrupted.reset()
                self.assertFalse(interrupted.is_primed)
                for index,price in enumerate(arrays['INPUT_CLOSE']):
                    output = module.fixture_update(interrupted,index,price,arrays)
                    for key,value in module.flatten_output(interrupted,output).items():
                        same_number(self,value,originals[index][key],0.0)

    def test_configuration_rejects_booleans_in_numeric_periods(self):
        for slug,module in STREAMING_MODULES.items():
            with self.subTest(indicator=slug):
                name,_ = module.PARAMETER_SHORTCUTS[0]
                with self.assertRaises(ValueError):
                    module.MASTER_CLASS(**{name:True})

    def test_constructor_cross_parameter_constraints(self):
        cases = [
            ('cycle-swing-momentum',dict(fast_smoothing=1600,slow_smoothing=160)),
            ('detrended-rhythm-oscillators',dict(fast_length=50,slow_length=3)),
            ('goertzel-cycle-spectrum',dict(min_period=5,max_period=20,step=4)),
            ('cycle-polarity',dict(short_period=40,long_period=20)),
            ('composite-cycle',dict(periods=(20,20))),
            ('metonic-relative-strength-index',dict(delay1=8,delay2=8)),
            ('metonic-sentiment-index',dict(mode=2)),
            ('cyclic-smoothed-relative-strength-index',dict(leveling=50)),
        ]
        for slug,parameters in cases:
            with self.subTest(indicator=slug):
                with self.assertRaises(ValueError):
                    MODULES[slug].MASTER_CLASS(**parameters)


class FilterMathematicsTests(unittest.TestCase):
    def test_hp_matches_independent_dense_normal_equations(self):
        module = MODULES['hodrick-prescott-smoothing-and-detrending']
        rng = random.Random(537)
        for n in (6,9,15):
            prices = [100+rng.uniform(-5,5) for _ in range(n)]
            for penalty in (0.0,1.0,160.0,1600.0,100000.0):
                with self.subTest(n=n,penalty=penalty):
                    observed = module.hp_trend(prices,penalty)
                    expected = dense_hp(prices,penalty)
                    for left,right in zip(observed,expected):
                        same_number(self,left,right,2e-9)

    def test_hp_preserves_constant_and_linear_nullspace(self):
        module = MODULES['hodrick-prescott-smoothing-and-detrending']
        for prices in ([12.0]*50,[12.0+0.25*i for i in range(50)]):
            for observed,expected in zip(module.hp_trend(prices,1600),prices):
                same_number(self,observed,expected,1e-9)

    def test_hp_stream_endpoint_is_rolling_causal_solution(self):
        module = MODULES['hodrick-prescott-smoothing-and-detrending']
        indicator = module.HodrickPrescott(window=9,smoothing=16.0)
        prices = [100+math.sin(i*0.31)+0.1*i for i in range(25)]
        for index,price in enumerate(prices):
            output = indicator.update(price)
            if index<8:
                self.assertTrue(math.isnan(output.trend))
            else:
                expected = dense_hp(prices[index-8:index+1],16.0)[-1]
                same_number(self,output.trend,expected)
                same_number(self,output.cycle,price-expected)

    def test_csi_is_difference_of_two_independent_hp_endpoints(self):
        module = MODULES['cycle-swing-momentum']
        prices = [100+math.sin(i*0.63)+0.2*i for i in range(12)]
        indicator = module.CycleSwing(window=12,fast_smoothing=16,slow_smoothing=160,band_memory=2)
        outputs = [indicator.update(value) for value in prices]
        expected = dense_hp(prices,16)[-1]-dense_hp(prices,160)[-1]
        same_number(self,outputs[-1].value,expected)
        self.assertTrue(math.isnan(outputs[-1].score))

    def test_crsi_monotone_ramp_has_closed_form_smoothing(self):
        module = MODULES['cyclic-smoothed-relative-strength-index']
        indicator = module.CyclicSmoothedRSI(dominant_cycle=20,vibration=10)
        gamma = 2.0/11.0
        for index in range(100):
            output = indicator.update(100.0+index)
            if index<14:
                self.assertTrue(math.isnan(output.value))
            else:
                k = index-14+1
                same_number(self,output.value,100*(1-(1-gamma)**k))
            self.assertEqual(math.isnan(output.lower),index<53)

    def test_band_grid_and_constant_window_repairs(self):
        for slug in ('cyclic-smoothed-relative-strength-index','cycle-swing-momentum'):
            module = MODULES[slug]
            self.assertEqual(module._grid_bands([5.0]*40,10),(5.0,5.0))
            self.assertEqual(module._grid_bands(list(range(101)),10),(11.0,90.0))
            self.assertEqual(module._grid_bands(list(range(101)),25),(26.0,75.0))

    def test_wilder_seed_and_flat_convention(self):
        module = MODULES['metonic-relative-strength-index']
        rsi = module._WilderRSI(3)
        output = [rsi.update(value) for value in (10,12,11,14)]
        self.assertTrue(all(math.isnan(value) for value in output[:3]))
        same_number(self,output[-1],100-100/(1+5))
        flat = module._WilderRSI(3)
        self.assertEqual([flat.update(10) for _ in range(4)][-1],100)

    def test_zlema_length_one_identity_and_even_length_ema(self):
        module = MODULES['zero-lag-exponential-moving-average']
        identity,ema = module.ZeroLagEMA(1),module.ZeroLagEMA(2)
        reference = None
        for price in (100.0,102.0,101.0,109.0,98.0):
            self.assertEqual(identity.update(price),price)
            reference = price if reference is None else 2/3*price+1/3*reference
            same_number(self,ema.update(price),reference)

    def test_zlema_settled_ramp_delay(self):
        module = MODULES['zero-lag-exponential-moving-average']
        for length,delay in ((13,0.0),(10,0.5)):
            indicator = module.ZeroLagEMA(length)
            for index in range(400):
                output = indicator.update(100.0+index)
            same_number(self,output,499.0-delay)


class SpectralMathematicsTests(unittest.TestCase):
    def test_goertzel_matches_direct_complex_dft_at_fractional_periods(self):
        module = MODULES['goertzel-cycle-spectrum']
        prices = [math.sin(i*0.13)+0.4*math.cos(i*0.77)+0.01*i for i in range(97)]
        for period in (3.0,8.0,20.0,20.5,101.0):
            omega = 2*math.pi/period
            real = sum(value*math.cos(omega*i) for i,value in enumerate(prices))
            imaginary = -sum(value*math.sin(omega*i) for i,value in enumerate(prices))
            amplitude = 2*math.sqrt(real*real+imaginary*imaginary)/len(prices)
            phase = math.pi/2+math.atan2(imaginary,real)
            observed = module.goertzel(prices,period)
            same_number(self,observed.amplitude,amplitude)
            same_number(self,math.sin(observed.phase),math.sin(phase))
            same_number(self,math.cos(observed.phase),math.cos(phase))

    def test_coherent_sine_phase_origin_and_trough(self):
        module = MODULES['goertzel-cycle-spectrum']
        period,amplitude,phase = 20.0,3.0,0.37
        prices = [amplitude*math.sin(2*math.pi*i/period+phase) for i in range(100)]
        model = module.goertzel(prices,period)
        same_number(self,model.amplitude,amplitude)
        same_number(self,model.phase,phase)
        same_number(self,module.cycle_value(model,model.trough_offset),-amplitude)
        same_number(self,module.cycle_value(model,99),prices[-1])

    def test_zero_vector_phase_is_unavailable(self):
        module = MODULES['goertzel-cycle-spectrum']
        model = module.goertzel([0.0]*100,20)
        self.assertEqual(model.amplitude,0)
        self.assertTrue(math.isnan(model.phase))
        self.assertEqual(module.cycle_value(model,4),0)
        self.assertEqual(module.cycle_slope(model,4),0)

    def test_owned_heatmap_grid_and_dominant_tone(self):
        module = MODULES['goertzel-cycle-spectrum']
        indicator = module.GoertzelCycleSpectrum(window=120,min_period=10,max_period=30,step=10,smoothing=0)
        for i in range(120):
            output = indicator.update(4*math.sin(2*math.pi*i/20+0.3),time=i)
        self.assertEqual(output.dominant_period,20)
        self.assertEqual(output.heatmap.time,119)
        self.assertEqual(len(output.heatmap.values),3)
        original = output.heatmap.values.copy()
        indicator.update(3.1)
        self.assertEqual(output.heatmap.values,original)

    def test_bartels_perfect_consistency_ceiling(self):
        module = MODULES['bartels-periodicity-score']
        for segments in (2,5,7):
            prices = [math.sin(2*math.pi*i/20+0.3) for i in range(20*segments)]
            output = module.bartels_score(prices,20,segments,segments)
            same_number(self,output.score,math.exp(-segments))
            same_number(self,output.genuine_percent,100*(1-math.exp(-segments)))

    def test_bartels_opposite_phase_vectors_cancel(self):
        module = MODULES['bartels-periodicity-score']
        one = [math.sin(2*math.pi*i/20+0.3) for i in range(20)]
        output = module.bartels_score(one+[-value for value in one],20,2,2)
        same_number(self,output.score,1.0)

    def test_bartels_no_segment_or_no_energy_is_not_genuine(self):
        module = MODULES['bartels-periodicity-score']
        for data in ([1.0]*10,[0.0]*100):
            output = module.bartels_score(data,20)
            self.assertTrue(math.isnan(output.score))
            self.assertTrue(math.isnan(output.genuine_percent))

    def test_strength_formula_and_price_wrapper(self):
        module = MODULES['cycle-strength']
        same_number(self,module.cycle_strength(300,110),300/110)
        self.assertGreater(module.cycle_strength(200,60),module.cycle_strength(300,110))
        indicator = module.CycleStrength(window=100,period=20,smoothing=0)
        for i in range(100):
            output = indicator.update(3*math.sin(2*math.pi*i/20+0.3))
        same_number(self,output.strength,3/20)

    def test_composite_is_exact_superposition_on_coherent_tones(self):
        module = MODULES['composite-cycle']
        indicator = module.CompositeCycle(window=120,periods=(20,40),smoothing=0)
        def signal(i):
            return 3*math.sin(2*math.pi*i/20+0.2)+2*math.sin(2*math.pi*i/40-0.5)
        for i in range(120):
            output = indicator.update(signal(i))
        same_number(self,output.value,signal(119))
        same_number(self,output.next_value,signal(120))
        same_number(self,indicator.project(12),signal(131))
        slope = 3*2*math.pi/20*math.cos(2*math.pi*119/20+0.2)+2*2*math.pi/40*math.cos(2*math.pi*119/40-0.5)
        same_number(self,output.slope,slope)
        before = indicator.samples_seen
        indicator.project(200)
        self.assertEqual(indicator.samples_seen,before)

    def test_polarity_truth_table_and_tolerance(self):
        module = MODULES['cycle-polarity']
        for short,long,expected in ((1,2,1),(-1,-2,-1),(-1,2,0),(1,-2,0),(0,1,0)):
            self.assertEqual(module.cycle_polarity(short,long),expected)
        self.assertEqual(module.cycle_polarity(0.01,1,tolerance=0.1),0)


class RhythmTests(unittest.TestCase):
    def test_periodic_signal_has_completed_cycle_median(self):
        module = MODULES['detrended-rhythm-oscillators']
        indicator = module.DetrendedRhythmOscillator(zig_period=5,detrend=False)
        for i in range(300):
            output = indicator.update(100+math.sin(2*math.pi*i/20+0.3))
        self.assertEqual(output.cycle_length,20)
        self.assertTrue(indicator.is_cycle_primed)
        self.assertLessEqual(output.pivot_offset,0)

    def test_monotone_signal_does_not_fabricate_completed_cycle(self):
        module = MODULES['detrended-rhythm-oscillators']
        indicator = module.DetrendedRhythmOscillator(zig_period=5,detrend=False)
        for i in range(100):
            output = indicator.update(100+i)
        self.assertTrue(math.isnan(output.cycle_length))
        self.assertEqual(output.direction,1)

    def test_zero_extremum_is_recognized_as_a_real_pivot(self):
        module = MODULES['detrended-rhythm-oscillators']
        indicator = module.DetrendedRhythmOscillator(zig_period=5,detrend=False)
        for value in (1,2,3,2,1,0):
            indicator.update(value)
        self.assertEqual(indicator.direction,-1)
        self.assertEqual(indicator.pivots[0][0],0)
        self.assertTrue(any(value==3 for value,index in indicator.pivots))


class CalendarTests(unittest.TestCase):
    def test_full_payload_is_filled_before_indicator_calculation(self):
        module = MODULES['metonic-sentiment-index']
        payload=(100,102,99,101)
        observed=list(module.fill_calendar_days([(date(2020,1,3),payload),(date(2020,1,6),(101,103,100,102))]))
        self.assertEqual([row[0] for row in observed],[date(2020,1,i) for i in (3,4,5,6)])
        self.assertEqual(observed[1][1],payload)
        self.assertEqual(observed[2][1],payload)

    def test_calendar_gaps_rejected_before_mutation(self):
        module = MODULES['metonic-relative-strength-index']
        indicator=module.MetonicRSI(length=1,delay1=3,delay2=2,delay3=1)
        indicator.update(100,time=date(2020,1,1))
        with self.assertRaises(ValueError):
            indicator.update(101,time=date(2020,1,3))
        self.assertEqual(indicator.samples_seen,1)
        indicator.update(101,time=date(2020,1,2))
        with self.assertRaises(ValueError):
            indicator.update(102)
        self.assertEqual(indicator.samples_seen,2)

    def test_real_metonic_delays_original_signed_votes(self):
        module = MODULES['metonic-sentiment-index']
        indicator=module.MetonicSentimentIndex(length=1)
        votes=[]
        for i in range(7100):
            vote=1.0 if i%2==0 else -1.0
            votes.append(vote)
            output=indicator.update(100.0,open_price=99 if vote>0 else 101)
            if i<6939:
                self.assertTrue(math.isnan(output.value))
            else:
                self.assertEqual(output.value,sum(votes[i-delay] for delay in (6939,4016,2922)))

    def test_real_defaults_warmup_and_finite_outputs(self):
        sentiment=MODULES['metonic-sentiment-index'].MetonicSentimentIndex()
        rsi=MODULES['metonic-relative-strength-index'].MetonicRSI()
        williams=MODULES['metonic-williams-percent-r'].MetonicWilliamsR()
        for i in range(7000):
            s=sentiment.update(101,open_price=100)
            r=rsi.update(100+i)
            w=williams.update(100+i,high=101+i,low=99+i)
            self.assertEqual(math.isnan(s.value),i<6945)
            self.assertEqual(math.isnan(r.value),i<6952)
            self.assertEqual(math.isnan(w.value),i<6951)
        self.assertEqual(s.value,3)
        self.assertEqual(r.value,100)
        same_number(self,w.value,-100/14)

    def test_delayed_rsi_is_average_of_historical_states(self):
        module = MODULES['metonic-relative-strength-index']
        indicator=module.MetonicRSI(length=3,delay1=19,delay2=11,delay3=8)
        # Independent raw RSI from growing lists and explicit Wilder recurrence.
        prices=[100+math.sin(i*0.41)*5 for i in range(100)]
        gains=[max(prices[i]-prices[i-1],0) for i in range(1,len(prices))]
        losses=[max(prices[i-1]-prices[i],0) for i in range(1,len(prices))]
        up=sum(gains[:3])/3
        down=sum(losses[:3])/3
        reference=[math.nan]*3
        reference.append(100.0 if down==0 else 100-100/(1+up/down))
        for j in range(3,len(gains)):
            up=(2*up+gains[j])/3
            down=(2*down+losses[j])/3
            reference.append(100.0 if down==0 else 100-100/(1+up/down))
        for i,price in enumerate(prices):
            output=indicator.update(price)
            if i>=22:
                same_number(self,output.value,sum(reference[i-d] for d in (19,11,8))/3)

    def test_williams_uses_actual_hlc_and_keeps_undefined_days(self):
        module = MODULES['metonic-williams-percent-r']
        indicator=module.MetonicWilliamsR(length=1,delay1=3,delay2=2,delay3=1)
        first=indicator.update(5,high=5,low=5)
        self.assertTrue(math.isnan(first.linear_percent_r))
        for index in range(1,5):
            output=indicator.update(5,high=6,low=4)
            self.assertEqual(output.linear_percent_r,-50)
            if index<4:
                self.assertTrue(math.isnan(output.value))
            else:
                self.assertEqual(output.value,-50)

    def test_hlc_and_original_open_contracts_are_not_synthesized(self):
        williams=MODULES['metonic-williams-percent-r'].MetonicWilliamsR()
        with self.assertRaises(ValueError):
            williams.update(100)
        with self.assertRaises(ValueError):
            williams.update(100,high=99,low=98)
        self.assertEqual(williams.samples_seen,0)
        original=MODULES['metonic-sentiment-index'].MetonicSentimentIndex()
        with self.assertRaises(ValueError):
            original.update(100)
        self.assertEqual(original.samples_seen,0)


